/* Create related master records while the original job form stays intact in memory. */
let relatedJobContext=null;
function relatedJobSelection(key,id,current={}){if(key==='customers'){let customer=find('customers',id);if(!customer)throw Error('Customer was not saved.');let bike=find('bikes',current.bike);return {customer:id,bike:bike?.customer===id?bike.id:''}}if(key==='bikes'){let bike=find('bikes',id);if(!bike||!find('customers',bike.customer))throw Error('Select a vehicle linked to a saved customer.');return {customer:bike.customer,bike:id}}throw Error('Unsupported related record.')}
function addJobRelatedButtons(){let form=$('#billForm');if(!form||jobDraft?.key!=='jobs'||form.querySelector('.jobInlineAdd'))return;for(let [key,label,name] of [['customers','Add Customer','customer'],['bikes','Add Vehicle','bike']]){let field=form.querySelector('[name="'+name+'"]')?.closest('.field');if(!field)continue;let button=document.createElement('button');button.type='button';button.className='btn secondary small jobInlineAdd';button.dataset.jobRelated=key;button.innerHTML=icon('plus')+' '+label;button.onclick=()=>openJobRelatedRecord(key);field.append(button)}}
function bindRelatedJobSubmit(key){let context=relatedJobContext,form=$('#recordForm');if(!context||context.key!==key||!form||form.dataset.jobRelatedBound)return;form.dataset.jobRelatedBound='true';let submit=form.onsubmit;form.onsubmit=function(event){context.submitting=true;context.savedId='';context.candidateId=form.querySelector('[name="id"]')?.value||'';try{return submit.call(this,event)}finally{context.submitting=false}};let note=document.createElement('p');note.className='notice';note.textContent='Save to return to your Job Card and select this '+(key==='customers'?'customer':'vehicle')+'. Cancel returns without changing your Job Card.';form.querySelector('.formbody')?.prepend(note)}
function openJobRelatedRecord(key){let form=$('#billForm');if(!form||jobDraft?.key!=='jobs'||relatedJobContext)return;if(key==='bikes'&&!db.customers.length)return toast('Add a customer first, then add the vehicle.');let body=$('#modalBody'),draft=jobDraft,fragment=document.createDocumentFragment();let currentCustomer=form.querySelector('[name="customer"]')?.value||'',currentBike=form.querySelector('[name="bike"]')?.value||'';let initial=key==='customers'?{name:form.querySelector('[name="walkinName"]')?.value||'',mobile:form.querySelector('[name="walkinMobile"]')?.value||'',address:form.querySelector('[name="walkinAddress"]')?.value||''}:{customer:currentCustomer,number:form.querySelector('[name="walkinNumber"]')?.value||''};relatedJobContext={key,draft,form,fragment,title:$('#modalTitle').innerHTML,dialogClass:$('.dialog').className,currentCustomer,currentBike,previousFocus:lastFocus};while(body.firstChild)fragment.appendChild(body.firstChild);jobDraft=null;try{editRecord(key,null,initial)}catch(error){restoreRelatedJob();toast(error.message)}}
function ensureRelatedOption(select,id,label){if(!select||!id)return;if(!Array.from(select.options).some(o=>o.value===id)){let option=document.createElement('option');option.value=id;option.textContent=label;select.appendChild(option)}select.value=id}
function restoreRelatedJob(){let context=relatedJobContext;if(!context)return;relatedJobContext=null;closeSearchSelect();let body=$('#modalBody');body.replaceChildren(context.fragment);$('#modalTitle').innerHTML=context.title;$('.dialog').className=context.dialogClass;$('#modal').hidden=false;document.body.style.overflow='hidden';jobDraft=context.draft;lastFocus=context.previousFocus;let form=context.form;if(context.savedId){try{let selection=relatedJobSelection(context.key,context.savedId,{customer:context.currentCustomer,bike:context.currentBike});let customer=form.querySelector('[name="customer"]'),bike=form.querySelector('[name="bike"]');setWalkinMode(form,false);ensureRelatedOption(customer,selection.customer,name('customers',selection.customer));customer.dispatchEvent(new Event('change',{bubbles:true}));if(selection.bike)ensureRelatedOption(bike,selection.bike,number(selection.bike));else if(bike)bike.value='';Object.assign(jobDraft.record,selection);jobDraft.record.vehicleNumber=selection.bike?number(selection.bike):'';bike?.dispatchEvent(new Event('change',{bubbles:true}));toast((context.key==='customers'?'Customer':'Vehicle')+' saved and selected. Your Job Card details are preserved.')}catch(error){toast(error.message)}}form._syncCustomerBilling?.();updateBillTotals();updateDatePresentation(body);form.querySelector('[data-job-related="'+context.key+'"]')?.focus()}
const editBeforeJobRelated=editRecord;
editRecord=function(key,id,initial){editBeforeJobRelated(key,id,initial);bindRelatedJobSubmit(key)};
const saveBeforeJobRelated=save;
save=function(message){let context=relatedJobContext,result=saveBeforeJobRelated(message);if(result!==false&&context?.submitting&&find(context.key,context.candidateId))context.savedId=context.candidateId;return result};
const closeBeforeJobRelated=closeModal;
closeModal=function(){if(relatedJobContext)return restoreRelatedJob();return closeBeforeJobRelated()};
const billBeforeJobRelated=billForm;
billForm=function(key,id,initial){billBeforeJobRelated(key,id,initial);if(key==='jobs')addJobRelatedButtons()};
